'use strict';
const fullImportState={options:{},historyId:'',field:'',page:0};
const fullButton=(label,action,kind='')=>button(label,'x-full-import-'+action,kind).replace('<button ','<button type="button" ');
async function fullImportApi(action,body){let response;try{response=await fetch('/api/import/full/'+action,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':appState.csrf||''},body:JSON.stringify(body),signal:AbortSignal.timeout(120000)});}catch{throw Error(action==='confirm'?'No se pudo confirmar el resultado. Revisa el historial antes de repetir la importación.':'No se pudo completar la revisión. Puedes retomar la captura guardada.');}const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo preparar la migración.');return result;}
extraUI.views.importar=function(){return heading('Toda tu historia, en Áurea.','Migración de Charles · captura íntegra, conciliación y confirmación del superadministrador.')+`<section class="card card-body import-full-intro"><span class="crm-beta">Migración completa</span><h2>Conserva el origen. Revisa la conversión.</h2><p>MongoDB se consulta en solo lectura: todas las colecciones y documentos de la base seleccionada, junto con sus metadatos. La captura original se conserva cifrada y se verifica por huella antes de guardar.</p><div class="import-full-steps"><span><strong>01</strong> Capturar</span><span><strong>02</strong> Conciliar</span><span><strong>03</strong> Confirmar</span></div><p class="muted">Ventas, compras, abonos, créditos, cierres, caja, cuentas, catálogo y contactos pasan a sus módulos. Los campos adicionales permanecen íntegros en el archivo protegido. Los usuarios importados requieren revisión de acceso. Se conserva la identidad Áurea.</p><p class="muted">Puedes importar en una base vacía o preparar una nueva conservando tu base actual. Las diferencias bloquean la confirmación. Las ventas sin costo histórico se conservan y sus periodos no mostrarán una utilidad inventada.</p></section>${data().sales.some(x=>x.costUnknown)?'<section class="card card-body crm-spacing"><h2>Costos históricos pendientes</h2><p>Documenta los costos que faltan con sus soportes. Los originales de Charles seguirán intactos.</p>'+fullButton('Documentar costo de una venta','costs','primary')+'</section>':''}<div class="grid-equal import-grid crm-spacing"><section class="card"><div class="card-head"><h2>Capturar desde MongoDB</h2></div><div class="card-body">${'<div id="charles-local-connection"></div>'+pForm('full-charles-mongo-form',input('URI de MongoDB · cuenta de solo lectura','uri','','password','required autocomplete="off" spellcheck="false" placeholder="mongodb+srv://…"')+input('Base de datos completa','database','charlesjoyas_pos','text','required maxlength="100"')+'<p class="muted">Solo consulta. Incluye todas las colecciones, sin limitarse a nexusdatas. Requiere lectura y listado, y soporte de snapshot. La URI no se guarda. Para capturas grandes, migra desde la instalación local y transfiere su base a Turso. El límite local es 128 MB. La revisión se guarda cifrada durante siete días y puedes retomarla aunque reinicies Áurea.</p>','Capturar y revisar')}</div></section><section class="card"><div class="card-head"><h2>Revisar una copia JSON</h2></div><div class="card-body">${pForm('full-charles-json-form',input('Estado JSON o captura completa','file','','file','required accept=".json,application/json"')+'<p class="muted">Acepta db.json, un documento con content o una captura aurea-charles-full-v1. Un db.json contiene el estado de Charles; para incluir otras colecciones de Mongo, utiliza la conexión completa.</p>','Preparar vista previa')}</div></section></div><div id="charles-drafts"></div><div id="charles-operational-status"></div><div id="charles-prepared-databases"></div><div id="charles-preview"></div><section class="card crm-spacing"><div class="card-head"><h2>Migraciones e historial conservado</h2></div><div class="card-body" id="charles-imports">Consultando…</div></section><div id="charles-history"></div>`;};
function fullResolution(issue,p,i){const ref=issue.reference,o=fullImportState.options,contactKinds=/supplier|purchases|abonosCompras/.test(ref)?'suppliers':'customers',credits=contactKinds==='suppliers'?'supplierCredits':'customerCredits',contactOptions=(p.resolutionContacts?.[contactKinds]||[]).map(c=>[c.id,c.name+' · '+c.id]);let controls='';if(issue.code==='contact')controls=select('Asociar a contacto existente','resolution-'+i,[['','Selecciona después de revisar'],['__restore__','Recuperar como contacto histórico inactivo'],...contactOptions],o.links?.[ref]?.contactId||'');if(issue.code==='balance')controls=select('Saldo que conservará la operación','resolution-'+i,[['','Selecciona el saldo correcto'],['credits','Saldo de los créditos'],['contact','Saldo del contacto']],o.balances?.[ref]||'');if(issue.code==='account')controls=select('Cuenta del movimiento histórico','resolution-'+i,[['','Selecciona después de revisar'],['__unassigned__','Conservar sin cuenta identificada'],...(p.resolutionAccounts||[]).map(name=>[name,name])],o.links?.[ref]?.account||'');if(issue.code==='account-balance')controls=input('Saldo al corte de migración (COP)','resolution-'+i,o.accounts?.[ref.slice(9)]??'','number','step="0.01"');if(issue.code==='credit-link')controls=select('Crédito al que pertenece el abono','resolution-'+i,[['','Selecciona el crédito'],['__unallocated__','Conservar abono histórico sin asociar a una factura'],...(p.resolutionContacts?.[credits]||[]).map(c=>[c.id,c.name+' · '+c.id])],o.links?.[ref]?.creditId||'');if(issue.code==='product-sku')controls=input('SKU único en Áurea','resolution-'+i,o.products?.[ref.slice(9)]?.sku||issue.context?.suggestedSku||'','text','maxlength="100"');if(issue.code==='product-unit')controls=select('Medida revisada','resolution-'+i,[['','Selecciona tras verificar el producto'],['Unidades','Unidades (requiere existencia entera)'],['Pesaje','Pesaje (existencia en gramos)']],o.products?.[ref.slice(9)]?.measureType||'')+input('Existencia revisada (opcional)','stock-'+i,o.products?.[ref.slice(9)]?.stock??'','number','step="0.000001" min="0"');if(issue.code==='shift-link')controls=select('Asociación de turno revisada','resolution-'+i,[['','Selecciona tras revisar el cierre'],['unassigned','Conservar referencia sin turno (no existe el cierre)'],...(p.resolutionShifts||[]).map(sh=>[sh.id,sh.name])],o.shifts?.[ref.slice(7)]||'');if(issue.code==='date')controls=input('Fecha documentada','resolution-'+i,o.dates?.[ref]||'','date');if(issue.code==='method')controls=select('Medio de pago revisado','resolution-'+i,[['','Selecciona'],['cash','Efectivo'],['card','Tarjeta'],['transfer','Transferencia']],o.links?.[ref]?.method||'');return controls?`<article class="import-resolution"><h3>${esc(issue.context?.name||ref)}</h3><small>${esc(ref)}</small>${issue.context?.sku?`<p>SKU original: ${esc(issue.context.sku)} · Existencia: ${esc(issue.context.stock??'')} · ${esc(issue.context.measureType||'')}</p>`:''}<p>${esc(issue.message)}</p>${controls}</article>`:'';}
const preFullPreview=renderImportPreview;renderImportPreview=function(){const p=executiveState.preview;if(p?.mode!=='full')return preFullPreview();const target=document.querySelector('#charles-preview');if(!target)return;fullImportState.options=p.options||fullImportState.options;const issues=p.issues||[],totals=p.totals||{},unique=issues.filter((x,i)=>x.severity==='error'&&issues.findIndex(y=>y.code===x.code&&y.reference===x.reference)===i);target.innerHTML=`<section class="card crm-spacing"><div class="card-head"><div><h2>Revisión de migración</h2><small>Destino: ${p.destination==='new'?'base nueva; la actual se conserva':p.destination==='replace'?'sustituir datos de prueba de la base actual, con respaldo':'base actual'} · Captura ${p.sourceScope==='database-snapshot'?'de toda la base MongoDB':'del estado JSON de Charles'} · aún no importada</small></div><span class="crm-beta">${p.errors.length?p.errors.length+' bloqueos':p.rehearsal?.passed?'Ensayo aprobado':'Lista para ensayar'}</span></div><div class="card-body"><p class="muted">Revisión guardada · puedes retomarla hasta ${fmtDate(p.expires)}.</p><p class="muted">Huella de origen: <code>${esc(p.digest)}</code></p><div class="kpis workflow-kpis crm-spacing">${kpi('Ventas históricas',p.counts.recentTransactions||p.counts.sales||0)+kpi('Compras',p.counts.purchases||0)+kpi('Cartera',money(totals.receivables))+kpi('Proveedores',money(totals.payables))}</div><div class="kpis workflow-kpis">${kpi('Inventario al costo',money(totals.stockCost))+kpi('Ventas reconocidas',money(totals.recognizedSales))+kpi('Caja de corte',money(totals.cash))+kpi('Bancos de corte',money(totals.bank))}</div><details class="comms-config"><summary>Cobertura: cada campo del estado y cada colección</summary>${table(['Campo de Charles','Registros','Tratamiento'],(p.coverage||[]).map(c=>`<tr><td>${esc(c.field)}</td><td>${c.records}</td><td>${esc(c.handling)}</td></tr>`))}${table(['Colección Mongo / JSON','Documentos','Huella'],(p.manifest||[]).map(c=>`<tr><td>${esc(c.name)}</td><td>${c.documents}</td><td><code>${esc(c.digest.slice(0,20))}…</code></td></tr>`))}</details><details class="comms-config"><summary>Observaciones que debes revisar (${p.warnings.length})</summary><ul>${p.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')}</ul></details>${p.errors.length?`${p.errors.some(e=>e.includes('Áurea contiene')||e.includes('Ya existe información CRM'))?'<div class="info-strip"><strong>Tu base actual tiene datos.</strong><p>Puedes preparar una base nueva con tus accesos de Áurea. La base actual se conserva completa.</p>'+(appState.cloud?'<p>En Turso, usa una base independiente de pruebas o revisa la sustitución con respaldo.</p>':fullButton('Preparar en una base nueva','new-destination','primary'))+'</div>':''}<div class="info-strip"><strong>La migración está bloqueada.</strong> Resuelve las diferencias sobre esta copia. Charles permanece intacto.</div><details class="comms-config"><summary>Ver todos los bloqueos</summary><ul>${p.errors.map(e=>'<li>'+esc(e)+'</li>').join('')}</ul></details>`:''}${p.destination==='replace'?'<div class="info-strip"><strong>Sustitución de los datos de prueba</strong><p>Al confirmar se respaldará toda la base actual y se sustituirá su operación y CRM por la conversión de Charles. Se conservan tus accesos de Áurea y el historial de auditoría. Charles permanece en solo lectura.</p></div>':fullButton('Sustituir datos existentes al confirmar','replace-destination')}${pForm('full-charles-review-form',fullBalanceReview(p)+unique.map((x,i)=>fullResolution(x,p,i)).join('')+`<details class="comms-config"><summary>Resoluciones avanzadas y costos históricos documentados</summary><label class="field"><span>JSON de resoluciones (se aplica solo en la copia de migración)</span><textarea name="options" rows="9" spellcheck="false">${esc(JSON.stringify(fullImportState.options,null,2))}</textarea></label><p class="muted">Claves: links, balances, accounts, products, dates, shifts, costs. Los costos se expresan por línea: {"costs":{"recentTransactions:ID:0":12345}}. Usa únicamente datos documentados. No incluyas contraseñas ni URI.</p></details>`,'Guardar revisión y recalcular')}${fullPendingReview(p)}${fullRehearsalView(p)}${!p.errors.length&&p.rehearsal?.passed?pForm('full-charles-confirm-form',input('Escribe MIGRAR CHARLES COMPLETO','confirmation','','text','required autocomplete="off"')+'<p class="muted">Se creará un respaldo de Áurea. La copia cifrada original se verificará antes de confirmar toda la escritura en una transacción. Respalda además charles-migration.key en un lugar protegido.</p>','Confirmar migración completa'):''}${fullButton('Descartar captura','cancel','text')}</div></section>`.replaceAll('Datos guardados en Áurea','Vista previa · todavía sin importar');};
const preFullLoadImports=loadImports;loadImports=async function(){const target=document.querySelector('#charles-imports');if(!target)return;try{const [r,drafts,status,connection,prepared]=await Promise.all([api('/api/import/list'),api('/api/import/full/drafts'),api('/api/import/full/status'),api('/api/import/full/connection'),api('/api/import/full/prepared')]);if(!target.isConnected)return;renderFullDrafts(drafts.drafts);renderPreparedDatabases(prepared.databases);renderFullStatus(status);const local=document.querySelector('#charles-local-connection');if(local)local.innerHTML=connection.available?'<div class="info-strip"><strong>Conexión local de Charles detectada</strong><p>Captura completa en solo lectura, utilizando su configuración existente. Las credenciales permanecen protegidas.</p>'+fullButton('Capturar conexión local de Charles','local-source','primary')+'</div>':'';executiveState.imports=r.imports;target.innerHTML=r.imports.length?r.imports.map(i=>`<div class="list-item"><div class="list-text"><strong>${i.summary.mode==='full'?'Migración completa':'Importación inicial'} · ${fmtDate(i.createdAt)}</strong><small>${i.summary.counts.products||0} productos · ${esc(i.digest.slice(0,16))} · respaldo ${esc(i.summary.backup)}</small>${i.summary.archiveVerified?'<small>Copia íntegra verificada y cifrada</small>':''}</div>${i.summary.mode==='full'?fullButton('Consultar todo el origen','history-'+i.id):pButton('Consultar historial','import-history-'+i.id)}</div>`).join(''):'Aquí aparecerán las migraciones confirmadas y su respaldo.';}catch(e){target.textContent=e.message;}};
async function fullHistory(){const target=document.querySelector('#charles-history');if(!target)return;const q=new URLSearchParams({id:fullImportState.historyId,field:fullImportState.field||'__fields',page:fullImportState.page}),r=await api('/api/import/full/history?'+q);if(!target.isConnected)return;if(!fullImportState.field){fullImportState.field=r.fields.includes('recentTransactions')?'recentTransactions':r.fields[0];return fullHistory();}target.innerHTML=`<section class="card crm-spacing"><div class="card-head"><h2>Origen completo · consulta protegida</h2><span class="crm-beta">Huella verificada</span></div><div class="card-body">${pForm('full-history-filter',select('Campo o colección original','field',r.fields,fullImportState.field),'Consultar')}<p class="muted">Los campos sensibles permanecen cifrados y se muestran protegidos. Los originales se conservan; su presencia en este archivo no implica contabilizarlos otra vez.</p></div>${table(['Registro','Documento original'],r.rows.map((row,i)=>`<tr><td>${esc(row?.id||row?.key||i+1)}</td><td><details><summary>Ver contenido</summary><pre class="draft-preview">${esc(JSON.stringify(row,null,2))}</pre></details></td></tr>`))}<div class="card-body row">${r.page?fullButton('Anterior','history-prev'):''}<small>${r.total} registros · página ${r.page+1}</small>${(r.page+1)*50<r.total?fullButton('Siguiente','history-next'):''}</div></section>`;}
const preFullSubmit=extraUI.submit;extraUI.submit=async function(form,v){if(form.id==='full-charles-mongo-form'||form.id==='full-charles-json-form'){let payload;if(form.elements.file){const file=form.elements.file.files[0];if(appState.cloud&&file?.size>2800000)throw Error('En la nube el JSON admite hasta 2,8 MB. Para copias mayores, realiza la migración completa desde la instalación local y usa la transferencia a Turso.');if(!file||file.size>128*1024*1024)throw Error('Selecciona una copia JSON de hasta 128 MB.');let data;try{data=JSON.parse(await file.text());}catch{throw Error('Archivo JSON inválido.');}payload={source:'json',data};}else payload={source:'mongo',uri:v.uri,database:v.database};fullImportState.options={};try{executiveState.preview=await fullImportApi('preview',payload);}finally{if(form.elements.uri)form.elements.uri.value='';}renderImportPreview();loadImports();return null;}if(form.id==='full-charles-review-form'){let options;try{options=JSON.parse(v.options||'{}');if(!options||typeof options!=='object'||Array.isArray(options))throw Error();}catch{throw Error('El JSON de resoluciones no es válido.');}const issues=executiveState.preview.issues||[],unique=issues.filter((x,i)=>x.severity==='error'&&issues.findIndex(y=>y.code===x.code&&y.reference===x.reference)===i);unique.forEach((x,i)=>{const value=v['resolution-'+i],ref=x.reference;if(!value)return;const set=(section,key,value)=>{options[section]??={};options[section][key]=value;};const setLink=(key)=>{options.links??={};options.links[ref]??={};options.links[ref][key]=value;};if(x.code==='contact')setLink('contactId');if(x.code==='balance')set('balances',ref,value);if(x.code==='account')setLink('account');if(x.code==='credit-link')setLink('creditId');if(x.code==='method')setLink('method');if(x.code==='account-balance')set('accounts',ref.slice(9),Number(value));if(x.code==='date')set('dates',ref,value);if(x.code==='shift-link')set('shifts',ref.slice(7),value);if(['product-sku','product-unit'].includes(x.code)){options.products??={};const patch=options.products[ref.slice(9)]??={};patch[x.code==='product-sku'?'sku':'measureType']=value;if(v['stock-'+i]!==undefined&&v['stock-'+i]!=='')patch.stock=Number(v['stock-'+i]);}});for(const [i,account] of (executiveState.preview.balanceChecks||[]).entries()){const value=v['bank-balance-'+i];if(value!==undefined&&value!==''){options.accounts??={};options.accounts[account.name]=Number(value);}}fullImportState.options=options;executiveState.preview=await fullImportApi('review',{previewId:executiveState.preview.previewId,options});renderImportPreview();return null;}if(form.id==='full-charles-confirm-form'){const r=await fullImportApi('confirm',{previewId:executiveState.preview?.previewId,confirmation:v.confirmation});executiveState.preview=null;await load();render();toast(r.destination==='new'?'Base migrada preparada. Puedes abrirla conservando tu base anterior.':r.alreadyImported?'Esta captura ya estaba importada.':'Migración guardada. Copia íntegra verificada; revisa los accesos de los usuarios.');return null;}if(form.id==='full-cost-select-form'){return showFullCost(v.id);}if(form.id==='full-cost-document-form'){const sale=data().sales.find(x=>x.id===form.dataset.id);return {command:'migration.cost.document',body:{id:sale.id,evidence:v.evidence,lines:sale.items.map((_,i)=>Number(v['cost-'+i]))}};}if(form.id==='full-history-filter'){fullImportState.field=v.field;fullImportState.page=0;await fullHistory();return null;}return preFullSubmit(form,v);};
const preFullAction=extraUI.action;extraUI.action=async function(a,t){if(!a.startsWith('x-full-import-'))return preFullAction(a,t);const x=a.slice(14);if(x==='new-destination'||x==='replace-destination'){executiveState.preview=await fullImportApi('review',{previewId:executiveState.preview.previewId,options:fullImportState.options,destination:x==='replace-destination'?'replace':'new'});renderImportPreview();loadImports();return;}if(x.startsWith('open-prepared-')){const r=await fullImportApi('open-prepared',{id:x.slice(14)});modal('Base migrada disponible','<p>La base anterior se conserva. Accede a la base migrada con tus credenciales de Áurea.</p><p><a class="btn primary" target="_blank" rel="noopener" href="'+esc(r.url)+'">Abrir Áurea con los datos migrados</a></p>');loadImports();return;}if(x==='local-source'){fullImportState.options={};executiveState.preview=await fullImportApi('preview',{source:'charles-local'});renderImportPreview();loadImports();return;}if(x==='rehearsal'){executiveState.preview=await fullImportApi('rehearsal',{previewId:executiveState.preview.previewId});renderImportPreview();loadImports();return;}if(x.startsWith('resume-')){executiveState.preview=await fullImportApi('resume',{previewId:x.slice(7)});fullImportState.options=executiveState.preview.options||{};renderImportPreview();return;}if(x.startsWith('discard-')){await api('/api/import/cancel',{method:'POST',body:JSON.stringify({previewId:x.slice(8)})});if(executiveState.preview?.previewId===x.slice(8)){executiveState.preview=null;document.querySelector('#charles-preview').innerHTML='';}return loadImports();}if(x==='costs')return modal('Costos históricos pendientes',pForm('full-cost-select-form',select('Venta por documentar','id',data().sales.filter(x=>x.costUnknown&&x.items.length).map(x=>[x.id,(x.legacyId||x.id)+' · '+x.customer+' · '+fmtDate(x.date)])),'Revisar venta'));if(x==='cancel'){if(executiveState.preview)await api('/api/import/cancel',{method:'POST',body:JSON.stringify({previewId:executiveState.preview.previewId})});executiveState.preview=null;render();return;}if(x.startsWith('history-')){if(x==='history-next')fullImportState.page++;else if(x==='history-prev')fullImportState.page=Math.max(0,fullImportState.page-1);else{fullImportState.historyId=x.slice(8);fullImportState.field='';fullImportState.page=0;}return fullHistory();}};
const preFullModal=extraUI.modal;extraUI.modal=function(){preFullModal?.();document.querySelectorAll('#full-charles-mongo-form [data-action^="x-generate-"]').forEach(b=>b.remove());};

function showFullCost(id){const sale=data().sales.find(x=>x.id===id);if(!sale)throw Error('Venta no encontrada.');modal('Documentar costo · '+(sale.legacyId||sale.id),pForm('full-cost-document-form','<p>Registra el costo total histórico de cada línea, con un soporte verificable. No uses el costo actual del catálogo como sustituto.</p>'+sale.items.map((line,i)=>input(esc(line.name)+' · '+line.qty+' · costo total COP','cost-'+i,line.costUnknown?'':line.cost,'number','required min="0" step="1"')).join('')+'<label class="field"><span>Soporte y motivo</span><textarea name="evidence" rows="4" maxlength="1000" required></textarea></label>','Guardar costos documentados','data-id="'+esc(sale.id)+'"'));}

function fullRehearsalView(p){if(p.errors.length)return '';const r=p.rehearsal;return '<section class="import-rehearsal"><h3>Ensayo operativo antes de importar</h3><p>Probamos ventas, gramaje, abonos y compras en una copia temporal. Tu base operativa conserva sus datos.</p>'+fullButton(r?'Repetir ensayo':'Probar operación en copia temporal','rehearsal','primary')+(r?'<p class="'+(r.passed?'':'form-error')+'">'+(r.passed?'Ensayo aprobado. Ya puedes confirmar la migración.':'Hay una comprobación pendiente. Revisa los resultados.')+'</p>'+r.checks.map(c=>'<p>'+ (c.passed?'✓ ':'• ')+esc(c.name)+(c.message?' · '+esc(c.message):'')+'</p>').join(''):'')+'</section>';}
function renderFullDrafts(drafts){const target=document.querySelector('#charles-drafts');if(!target)return;target.innerHTML=drafts.length?'<section class="card crm-spacing"><div class="card-head"><h2>Revisiones guardadas</h2><small>Capturas cifradas · conservadas siete días</small></div><div class="card-body">'+drafts.map(d=>'<article class="list-item"><div class="list-text"><strong>'+fmtDate(d.updatedAt)+' · '+(d.counts.products||0)+' productos</strong><small>'+d.blockers+' bloqueos · '+(d.rehearsalPassed?'Ensayo aprobado':'Por revisar')+' · vence '+fmtDate(d.expires)+'</small></div><div class="row">'+fullButton('Retomar revisión','resume-'+d.id,'primary')+fullButton('Descartar','discard-'+d.id,'text')+'</div></article>').join('')+'</div></section>':'';}
function renderFullStatus(s){const target=document.querySelector('#charles-operational-status');if(!target)return;target.innerHTML=s.imported?'<section class="card card-body crm-spacing"><h2>Puesta en marcha de la migración</h2><p>Copia original '+(s.archiveVerified?'verificada':'por revisar')+' · ensayo al migrar '+(s.rehearsal?.passed?'aprobado':'no registrado en esta versión')+'.</p><div class="import-full-steps"><span><strong>'+s.usersToReview.length+'</strong> accesos por revisar</span><span><strong>'+s.contactsToReview.length+'</strong> contactos históricos por identificar</span><span><strong>'+s.historicalCostsPending+'</strong> costos históricos pendientes</span><span><strong>'+s.unassignedMovements+'</strong> movimientos históricos sin cuenta</span><span><strong>'+s.unallocatedPayments+'</strong> abonos históricos sin factura</span></div><p>Los costos históricos pendientes afectan la utilidad de esos periodos. Las operaciones nuevas conservan sus propios costos.</p><div class="row">'+button('Revisar usuarios','goto-usuarios')+button('Ver cartera','goto-cartera')+button('Ver proveedores','goto-creditos')+(s.historicalCostsPending?fullButton('Documentar costos','costs'):'')+'</div><p class="muted">Respaldo previo: '+esc(s.backup)+'. Conserva también la clave de recuperación en una ubicación protegida.</p></section>':'';}

function fullBalanceReview(p){return p.balanceChecks?.length?'<details class="comms-config"><summary>Conciliar saldos de cuentas al corte</summary><p>Contrasta estos saldos con tus soportes. Puedes documentar el saldo correcto sin cambiar Charles ni registrar ingresos nuevos.</p>'+p.balanceChecks.map((a,i)=>'<article class="import-resolution"><h3>'+esc(a.name)+'</h3><p>Propuesto según corte: '+money(a.proposedBalance)+' · Reconstruido del historial: '+money(a.ledgerBalance)+'</p>'+input('Saldo de corte verificado (opcional)','bank-balance-'+i,fullImportState.options.accounts?.[a.name]??'','number','step="0.01"')+'</article>').join('')+'</details>':'';}

function renderPreparedDatabases(databases){const target=document.querySelector('#charles-prepared-databases');if(!target)return;target.innerHTML=databases.length?'<section class="card crm-spacing"><div class="card-head"><h2>Bases migradas preparadas</h2><small>La base anterior se conserva completa</small></div><div class="card-body">'+databases.map(d=>'<article class="list-item"><div class="list-text"><strong>'+fmtDate(d.createdAt)+' · '+(d.summary.counts.products||0)+' productos</strong><small>Captura verificada · ensayo operativo aprobado · accesos originales de Áurea</small></div>'+fullButton('Abrir base migrada','open-prepared-'+d.id,'primary')+'</article>').join('')+'</div></section>':'';}

function fullPendingReview(p){const x=p.pending;if(!x||!Object.values(x).some(Number))return "";return `<div class="info-strip"><strong>Pendientes que se conservarán en la base migrada</strong><p>${x.prices} productos con precio por fijar en el POS · ${x.accounts} movimientos sin cuenta identificada · ${x.payments} abonos sin factura asociada · ${x.contacts} contactos históricos por identificar · ${x.historicalCosts} ventas sin costo histórico.</p><p>Estas decisiones conservan los datos faltantes del origen. Revisa las observaciones y los saldos de corte antes de confirmar. La confirmación no completa automáticamente esos datos.</p></div>`;}
